INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (1, 'Aventura en las Montanas', 118, 'Un grupo de exploradores busca una ciudad perdida en los Andes.', 1, 3);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (2, 'Risas en Familia', 95, 'Una familia numerosa organiza una boda caotica.', 2, 1);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (3, 'El Ultimo Verano', 124, 'Dos hermanos reviven recuerdos en el pueblo de su infancia.', 3, 3);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (4, 'La Casa del Lago', 101, 'Una pareja descubre secretos en su nueva casa.', 4, 5);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (5, 'Orbita Cero', 136, 'Una tripulacion queda atrapada en una estacion espacial.', 5, 3);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (6, 'Dino y sus Amigos', 88, 'Un pequeno dinosaurio busca su lugar en el mundo.', 6, 1);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (7, 'Cartas de Medianoche', 109, 'Un romance epistolar cruza dos ciudades.', 7, 2);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (8, 'Operacion Relampago', 127, 'Un agente especial debe frenar un atentado internacional.', 1, 4);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (9, 'Noche de Pesadilla', 97, 'Un grupo de amigos queda atrapado en un hospital abandonado.', 4, 5);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (10, 'El Robot Jardinero', 92, 'Un robot cuida el jardin de una anciana y aprende de la vida.', 6, 2);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (11, 'Mi Jefe es un Desastre', 104, 'Una oficina entera sufre las ocurrencias de su nuevo gerente.', 2, 3);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (12, 'Horizonte Final', 141, 'La humanidad busca un nuevo planeta antes de que sea tarde.', 5, 4);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (13, 'Bajo la Lluvia de Bogota', 112, 'Dos desconocidos se encuentran en una tarde lluviosa.', 7, 3);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (14, 'Sombras del Pasado', 130, 'Un detective investiga un caso que creia cerrado.', 3, 4);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (15, 'Super Gatos', 90, 'Tres gatos rescatan a su ciudad de un villano.', 6, 1);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (16, 'La Ruta del Cafe', 141, 'Una recolectora de cafe regresa a su pueblo y debe decidir entre conservar la finca familiar o venderla a una multinacional.', 2, 1);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (17, 'El Ultimo Viaje', 148, 'Un conductor de bus intermunicipal emprende un viaje que cambia su vida cuando recoge a un pasajero misterioso.', 3, 2);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (18, 'Cartas desde el Pacifico', 94, 'Una periodista investiga unas cartas encontradas en un puerto del Pacifico y descubre un secreto familiar.', 4, 3);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (19, 'Bajo el Cielo de Medellin', 101, 'Dos musicos se conocen durante un festival y deben superar sus diferencias para grabar un album juntos.', 5, 4);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (20, 'La Casa de los Espejos', 108, 'Una restauradora de patrimonio descubre mensajes ocultos en los espejos de una antigua casa colonial.', 6, 5);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (21, 'Guardianes del Amazonas', 115, 'Un grupo de jovenes protege una reserva natural del Amazonas mientras busca a un investigador desaparecido.', 7, 1);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (22, 'Tiempo Prestado', 122, 'Un cirujano recibe una segunda oportunidad profesional y debe enfrentar una decision que oculto durante anos.', 1, 2);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (23, 'El Misterio de la Hacienda', 129, 'Una familia campesina se reune en una hacienda y revive una historia de herencia, lealtad y perdon.', 2, 3);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (24, 'Una Historia de Barrio', 136, 'Un adolescente de barrio participa en un torneo de futbol y encuentra una nueva oportunidad para su familia.', 3, 4);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (25, 'La Isla de los Vientos', 143, 'Una biologa marina sigue la ruta de unos vientos inusuales que amenazan a una comunidad costera.', 4, 5);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (26, 'Codigo Jaguar', 150, 'Una agente ambiental persigue una red de trafico de fauna que opera entre varias regiones del pais.', 5, 1);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (27, 'El Tren de Medianoche', 96, 'Un maquinista queda atrapado en una estacion durante una tormenta y descubre que uno de los pasajeros miente.', 6, 2);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (28, 'Voces del Rio', 103, 'Un pescador del rio Magdalena busca a su hermano y reconstruye la historia de su familia.', 7, 3);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (29, 'La Promesa de Abril', 110, 'Una arquitecta recibe una propuesta inesperada justo cuando decide comenzar una nueva vida.', 1, 4);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (30, 'El Visitante', 117, 'Un visitante llega a un pueblo sin memoria y todos creen reconocerlo de una historia antigua.', 2, 5);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (31, 'Horizonte de Sal', 124, 'Una chef viaja al Caribe para recuperar una receta familiar y termina reconciliandose con su pasado.', 3, 1);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (32, 'La Sombra del Nevado', 131, 'Un montanista organiza un rescate en el Nevado del Ruiz mientras el clima empeora rapidamente.', 4, 2);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (33, 'Dias de Lluvia', 138, 'Una maestra rural intenta mantener abierta la escuela de su comunidad durante una temporada de lluvias.', 5, 3);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (34, 'El Camino de las Luciernagas', 145, 'Un fotografo sigue el rastro de unas luciernagas y encuentra una comunidad aislada en la montana.', 6, 4);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (35, 'Planeta Azul', 91, 'Una expedicion cientifica estudia un arrecife del Caribe y enfrenta una amenaza ambiental inesperada.', 7, 5);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (36, 'La Ultima Funcion', 98, 'El administrador de un cine antiguo prepara la ultima funcion mientras el barrio decide salvarlo de la demolicion.', 1, 1);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (37, 'Los Colores de la Memoria', 105, 'Una artista recopila recuerdos de varias familias y transforma sus historias en una exposicion.', 2, 2);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (38, 'Rescate en la Sierra', 112, 'Un equipo de rescatistas busca a un excursionista perdido en la Sierra Nevada.', 3, 3);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (39, 'Un Lugar para Volver', 119, 'Una mujer regresa a su ciudad natal para abrir una libreria y reencontrarse con un viejo amigo.', 4, 4);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (40, 'La Formula Imposible', 126, 'Dos estudiantes desarrollan un invento para solucionar un problema de agua en su colegio.', 5, 5);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (41, 'El Club de los Inventores', 133, 'Tres jovenes crean un club de ciencia y participan en una competencia nacional.', 6, 1);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (42, 'Noche en Cartagena', 140, 'Una chef organiza una cena en Cartagena que reune por accidente a personas de su pasado.', 7, 2);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (43, 'El Secreto de la Montana', 147, 'Un geologo descubre una cueva con pinturas antiguas y debe protegerla de los saqueadores.', 1, 3);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (44, 'Amigos por Accidente', 93, 'Dos desconocidos intercambian sus planes de viaje y terminan ayudandose a resolver problemas familiares.', 2, 4);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (45, 'La Ciudad Invisible', 100, 'Un grupo de vecinos construye un proyecto comunitario para recuperar un parque abandonado.', 3, 5);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (46, 'Aventura en el Pacifico', 107, 'Una reportera sigue la ruta de una ballena y documenta el impacto de la contaminacion marina.', 4, 1);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (47, 'El Guardian del Tiempo', 114, 'Un relojero recibe un objeto capaz de alterar pequenos momentos del pasado.', 5, 2);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (48, 'Bailando con Estrellas', 121, 'Una bailarina prepara una presentacion y encuentra apoyo en un grupo de ninos del barrio.', 6, 3);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (49, 'La Casa del Viento', 128, 'Una familia hereda una casa junto al viento y descubre por que nadie quiso habitarla.', 7, 4);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (50, 'Operacion Cordillera', 135, 'Un equipo especializado debe evacuar una comunidad aislada por un deslizamiento en la cordillera.', 1, 5);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (51, 'El Reino de los Gatos', 142, 'Una gata callejera se convierte en la mascota de un grupo de rescate animal.', 2, 1);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (52, 'Amor en la Plaza', 149, 'Una pareja se conoce durante una fiesta patronal y descubre que sus familias estan enfrentadas.', 3, 2);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (53, 'El Archivo Perdido', 95, 'Una archivista encuentra documentos que pueden resolver la desaparicion de un lider comunitario.', 4, 3);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (54, 'Viaje al Centro del Bosque', 102, 'Dos hermanos atraviesan un bosque protegido para cumplir la promesa que hicieron a su abuelo.', 5, 4);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (55, 'La Gran Carrera', 109, 'Un ciclista aficionado se prepara para la carrera mas importante de su vida.', 6, 5);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (56, 'El Eco de las Olas', 116, 'Un farero recibe una senal de auxilio y sale al mar durante una noche de tormenta.', 7, 1);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (57, 'Una Vida Nueva', 123, 'Una madre y su hija reconstruyen su relacion al administrar juntas un pequeno restaurante.', 1, 2);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (58, 'Mision: Altitud', 130, 'Un grupo de montanistas participa en una mision de rescate a gran altura.', 2, 3);
INSERT INTO pelicula (id_pelicula, titulo, duracion_min, sinopsis, id_genero, id_clasificacion) VALUES (59, 'El Faro del Fin del Mundo', 137, 'Un guardaparques protege un faro remoto mientras intenta contactar a su familia.', 3, 4);
